layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-radius: 0px; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="footer"] { color: rgb(107, 102, 93); background-color: var(--ryt-bg); border-top: 1px solid color-mix(in srgb, var(--ryt-text) 12%, transparent); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.15s cubic-bezier(0.4, 0, 0.2, 1), background-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), border-color 0.15s cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="brand"] { background-image: linear-gradient(115deg, var(--ryt-text) 6%, rgb(86, 83, 76) 94%); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-size: 16.8px; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: 2.352px; text-transform: none; text-decoration-style: solid; text-decoration-thickness: auto; text-underline-offset: auto; transition: all; background-clip: text; -webkit-text-fill-color: rgba(0, 0, 0, 0); -webkit-background-clip: text; -webkit-text-fill-color: transparent }
[data-ryt="header"] { border-bottom: 1px solid color-mix(in srgb, var(--ryt-text) 12%, transparent); border-top: none }
[data-ryt="nav"] a { color: rgb(107, 102, 93); border-radius: 0px; font-size: 14px; font-weight: 500; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(107, 102, 93); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
